            int next = -1;
            for (int i = prev + 1; i < 65536; i++) {
                if (freq[i] > 0) { next = i; break; }
            }
            if (next == -1) break;
            sb.append((char) next);
            freq[next]--; total--; prev = next;
        }
        if (total == 0) break;
        // 4. largest
        int d = -1;
        for (int i = 65535; i >= 0; i--) {
            if (freq[i] > 0) { d = i; break; }
        }
        if (d == -1) break;
        sb.append((char) d);
        freq[d]--; total--;
        int prev2 = d;
